using System.Text;
using System.Text.Json;
internal static class LibraryFolderTests {
 internal static async Task Run(){
  var temp=Path.Combine(Path.GetTempPath(),"LibraryFolderTest-"+Guid.NewGuid().ToString("N"));var source=Path.Combine(temp,"source");Directory.CreateDirectory(Path.Combine(source,"A"));Directory.CreateDirectory(Path.Combine(source,"B"));
  var previous=Environment.GetEnvironmentVariable("DLE_OS_SIM_DRAWING_ROOTS");Environment.SetEnvironmentVariable("DLE_OS_SIM_DRAWING_ROOTS",JsonSerializer.Serialize(new[]{new SimDrawingRoot("fixture","Fixture",source)}));
  try{
   var h=new SimAssemblyHeader("01PART                ","fixture","V1.2","PART                ","PART","A","202020","A",false);var headers=new[]{h,h with{SourceKeyRaw="01 PART               ",BillNumber=" PART               "}};
