   var described=JsonSerializer.SerializeToElement(await store.DescribeFolderTxt(key,new(f.Token,"A/bom.txt",""),viewer),SimLibraryBomStore.Json);var selection=new LibraryFolderSelection(f.Token,"A/bom.txt",described.GetProperty("sourceToken").GetString()!);
   var v=await store.Get(key,editor);v=await store.Change(new(key,v.Token,"START"),editor);
   await File.AppendAllTextAsync(path,"\n");await Reject(async()=>await store.Change(new(key,v.Token,"IMPORT",FileName:"bom.txt",FolderSelection:selection),editor),"changed source");Check((await store.Get(key,viewer)).Record.Draft!.Rows.Length==0,"rejected import unchanged");await File.WriteAllBytesAsync(path,bytes);
   described=JsonSerializer.SerializeToElement(await store.DescribeFolderTxt(key,new(f.Token,"A/bom.txt",""),viewer),SimLibraryBomStore.Json);selection=selection with{SourceToken=described.GetProperty("sourceToken").GetString()!};
   await Reject(async()=>await store.DescribeFolderTxt(key,new(f.Token,"B/bom.txt",""),viewer),"outside linked folder");
   v=await store.Change(new(key,v.Token,"IMPORT",FileName:"bom.txt",FolderSelection:selection),editor);Check(v.Record.Draft!.FolderEvidence!.Association.Id==f.Record.Current!.Id&&v.Record.Draft.EvidenceHash==before,"copied evidence provenance");Check((await store.Evidence(key,null,viewer)).SequenceEqual(bytes),"exact frozen copy");
   var frozen=JsonSerializer.Serialize(v.Record.Draft,SimLibraryBomStore.Json);f=await store.LinkFolder(new(key,f.Token,"fixture","B","A","A"),editor);Check(f.Record.History.Length==2,"remap audit");Check(JsonSerializer.Serialize((await store.Get(key,viewer)).Record.Draft,SimLibraryBomStore.Json)==frozen,"remap does not alter evidence");await Reject(async()=>await store.DescribeFolderTxt(key,selection,viewer),"old selection after remap");Check(SimLibraryBomStore.Hash(await File.ReadAllBytesAsync(path))==before,"source untouched by import");
   var both=P("assembly_library.view","assembly_library.edit","technical_review.view","technical_review.disposition");var row=v.Record.Draft!.Rows.Single();var edit=new LibraryRowEdit(row.Id,row.Find,row.SourcePartNumber,row.Description,row.Quantity,row.Unit,row.ReferenceDesignators,"CUSTOMER","","",true,false,"Fixture verified",false);
   v=await store.Change(new(key,v.Token,"SAVE",DrawingRevision:"A",BomRevision:"A",QuantityBasis:"PER_ASSEMBLY",PreparationAssessed:true,Rows:[edit]),both);v=await store.Change(new(key,v.Token,"SUBMIT"),both);var review=v.Record.Reviews.Last();v=await store.Change(new(key,v.Token,"APPROVE",ReviewId:review.Id,Comments:"Fixture review"),both,true);var approved=JsonSerializer.Serialize(v.Record.Reviews,SimLibraryBomStore.Json);f=await store.LinkFolder(new(key,f.Token,"fixture","A","A","A"),editor);Check(JsonSerializer.Serialize((await store.Get(key,viewer)).Record.Reviews,SimLibraryBomStore.Json)==approved,"approved evidence unaffected by remap");Check((await store.Evidence(key,review.Id,viewer)).SequenceEqual(bytes),"approved frozen bytes remain available");
   var legacy=v.Record.Reviews.Last().Snapshot with{FolderEvidence=null};Check(!JsonSerializer.Serialize(legacy,SimLibraryBomStore.Json).Contains("folderEvidence"),"legacy snapshot hash serialization preserved");
