   var key2=headers[1].SourceKeyRaw;var f2=await store.Folder(key2,viewer);f2=await store.LinkFolder(new(key2,f2.Token,"fixture","A","A","A"),editor);var v2=await store.Get(key2,editor);v2=await store.Change(new(key2,v2.Token,"START"),editor);v2=await store.Change(new(key2,v2.Token,"SAVE",DrawingRevision:"A",BomRevision:"B",Rows:[]),editor);await Reject(async()=>await store.DescribeFolderTxt(key2,new(f2.Token,"A/bom.txt",""),viewer),"revision mismatch");
   for(int i=0;i<205;i++)await File.WriteAllTextAsync(Path.Combine(source,"B",i+".txt"),"fixture");var listing=await store.BrowseFolder(key,"fixture","B",viewer);Check(listing.Truncated&&listing.Entries.Length==200,"bounded listing");
   var junction=Path.Combine(source,"junction");var psi=new System.Diagnostics.ProcessStartInfo("cmd.exe"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};psi.ArgumentList.Add("/c");psi.ArgumentList.Add("mklink");psi.ArgumentList.Add("/J");psi.ArgumentList.Add(junction);psi.ArgumentList.Add(Path.Combine(source,"A"));using var process=System.Diagnostics.Process.Start(psi)!;await process.WaitForExitAsync();Check(process.ExitCode==0,"fixture junction creation");await Reject(async()=>await store.BrowseFolder(key,"fixture","junction",viewer),"reparse rejected");
   Console.WriteLine("PASS Library folder persistence/history/concurrency, raw key and revision separation, permissions, bounded listing/traversal/reparse, source freshness, explicit import and frozen provenance, unchanged source and BOM on remap.");
  }finally{Environment.SetEnvironmentVariable("DLE_OS_SIM_DRAWING_ROOTS",previous);}
 }
}
